use vstd::prelude::*;

verus! {
    /// Constructs a length‐2 vector containing exactly the two given `f32` values.
    fn vec2(a: f32, b: f32) -> (result: Vec<f32>)
        ensures
            result.len() == 2,
            result[0] == a,
            result[1] == b
    {
        let mut v: Vec<f32> = Vec::new();
        // After each push, Verus knows how len and contents evolve.
        v.push(a);
        v.push(b);
        // Return the freshly built vector
        v
    }

    /// A specialized two‐point vector for a "leg line", reusing `vec2`.
    fn legline(off: f32, scl: f32) -> (result: Vec<f32>)
        ensures
            result.len() == 2,
            result[0] == off,
            result[1] == scl
    {
        // Delegate to vec2; its postconditions prove ours immediately
        vec2(off, scl)
    }
}

